sun.position.set(5, 10, 8);
scene.add(sun);
const fill = new THREE.DirectionalLight(0xa0c0e0, 0.3);
fill.position.set(-5, 3, -5);
scene.add(fill);

/* ── Helpers ───────────────────────────────────────────────────────────── */
function flatMat(color, opts={}) {
  return new THREE.MeshLambertMaterial({ color, flatShading:true, ...opts });
}

/* ── Mt. Fuji — distant background ─────────────────────────────────────── */
function buildFuji() {
  const g = new THREE.Group();

  // Main cone
  const coneGeo = new THREE.ConeGeometry(12, 14, 8, 3);
  const pos = coneGeo.attributes.position;
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i), y = pos.getY(i), z = pos.getZ(i);
    pos.setX(i, x + Math.sin(x*3.7 + z*2.1) * 0.25);
    pos.setZ(i, z + Math.cos(x*2.1 + z*3.7) * 0.2);
  }
  coneGeo.computeVertexNormals();
  const cone = new THREE.Mesh(coneGeo, flatMat(PAL.fujiBase));
  cone.position.y = 7;
  g.add(cone);

  // Snow cap
  const snowGeo = new THREE.ConeGeometry(5, 5.5, 8, 2);
  const sPos = snowGeo.attributes.position;
  for (let i = 0; i < sPos.count; i++) {
    const x = sPos.getX(i), y = sPos.getY(i), z = sPos.getZ(i);
    sPos.setX(i, x + Math.sin(x*4+z*3)*0.2);
    sPos.setZ(i, z + Math.cos(x*3+z*4)*0.2);
  }
  snowGeo.computeVertexNormals();
  const snow = new THREE.Mesh(snowGeo, flatMat(PAL.fujiSnow));
  snow.position.y = 11;
  g.add(snow);

  // Shadow side
  const shadowGeo = new THREE.ConeGeometry(12.1, 14.1, 8, 3);
  const shadow = new THREE.Mesh(shadowGeo, flatMat(PAL.fujiShadow));
  shadow.position.set(-0.5, 6.9, -0.5);
  shadow.scale.set(1.01, 1, 1.01);
  g.add(shadow);

  return g;
}

